#!/bin/bash
# apply_full_rebuild_pass1-6_plus_playful_blue_ui.sh
#
# Your uploaded project (dracarys-fx-pro_2026-08-09_13-29-20.zip) predates
# the entire app.js decomposition series (passes 1-6: format.js, chart.js,
# paperTrading.js, labels.js, testerRender.js, backtestRender.js,
# candleBuffer.js, executionDecision.js, marketSelection.js) AND the
# Playful Blue UI pass (colored KPI cards, welcome greeting, card
# reordering, View All links, notification badge). Those were built and
# verified against a separately-uploaded, more current snapshot of your
# project (dracarys-fx-pro-20260810-205322.zip).
#
# Rather than replaying six historical patch scripts I don't have on top
# of this older tree, this script does a full source replacement: it
# overwrites frontend/src, frontend/tests, frontend/api, frontend/index.html,
# frontend/vite.config.js, frontend/package.json, frontend/vitest.config.js,
# backend/, scripts/, root package.json, and README.md with the current,
# fully-patched versions - already verified (196/196 tests, clean build,
# 191/191 imports resolving) against the newer snapshot.
#
# PRESERVED, NOT TOUCHED (this script never writes to these):
#   - frontend/.env, frontend/.env.example  (your real API keys/webhook)
#   - frontend/data/                         (your live SQLite DB + logs)
#   - frontend/reports/                      (generated report HTML)
#   - .vercel/                               (your Vercel project link)
#
# WHAT YOU LOSE: any manual edits you made directly to frontend/src, tests,
# backend/, or scripts/ in THIS Aug 9 snapshot that were never captured in
# the Aug 10 snapshot. If you're not sure, this script backs up your
# current tree first (see below) - diff against the backup afterward if
# you want to recover anything.
#
# Run from the ROOT of your project (the folder containing frontend/):
#
#   chmod +x apply_full_rebuild_pass1-6_plus_playful_blue_ui.sh
#   ./apply_full_rebuild_pass1-6_plus_playful_blue_ui.sh
#   cd frontend && npm install && npm test && npm run build
#
set -euo pipefail

if [ ! -d "frontend" ] || [ ! -f "frontend/package.json" ]; then
  echo "ERROR: run this from the root of your project (the folder containing frontend/)." >&2
  exit 1
fi

BACKUP_DIR=".dracarys-fix-backup-$(date +%Y%m%d-%H%M%S)"
echo "Backing up current project to ${BACKUP_DIR}/ ..."
mkdir -p "${BACKUP_DIR}"
for p in frontend/src frontend/tests frontend/api frontend/index.html \
         frontend/vite.config.js frontend/package.json frontend/vitest.config.js \
         backend scripts package.json README.md; do
  if [ -e "$p" ]; then
    mkdir -p "${BACKUP_DIR}/$(dirname "$p")"
    cp -R "$p" "${BACKUP_DIR}/$p"
  fi
done

echo "Extracting updated project files (payload embedded below) ..."
TMP_TAR="$(mktemp)"
awk '/^__PAYLOAD_BELOW__$/{found=1; next} found' "$0" | base64 -d > "$TMP_TAR"
tar xzf "$TMP_TAR" -C .
rm -f "$TMP_TAR"

echo ""
echo "Done. Your original files are backed up in ${BACKUP_DIR}/."
echo "Untouched (never overwritten): frontend/.env, frontend/data/, frontend/reports/, .vercel/"
echo ""
echo "Next steps:"
echo "  cd frontend && npm install && npm test && npm run build"
echo ""
exit 0

__PAYLOAD_BELOW__

